from itertools import product
from typing import Tuple
Vector = Tuple[bool, ...]
def implies(p: Vector, q: Vector) -> bool:
    return all((not a) or b for a, b in zip(p, q))
def count_uniform(worlds: int) -> tuple[int, int]:
    vectors = list(product((False, True), repeat=worlds))
    uniform = sum(all(not (implies(p, q) and any(q)) or all(p) for q in vectors) for p in vectors)
    return uniform, sum(all(p) for p in vectors)
for n in range(1, 6):
    print(n, count_uniform(n))

from typing import Sequence
Vector = tuple[bool, ...]
def conjunction(qs: Sequence[Vector]) -> Vector:
    if not qs: raise ValueError("Supply at least one vector")
    return tuple(all(q[i] for q in qs) for i in range(len(qs[0])))
def counterexamples(p: Vector, qs: Sequence[Vector]) -> list[int]:
    joint = conjunction(qs)
    return [i for i, (c, target) in enumerate(zip(joint, p)) if c and not target]
p = (True, False, False, False)
qs = [(True, True, False, False), (True, False, True, False)]
print("joint conjunction:", conjunction(qs))
print("certificate counterexamples:", counterexamples(p, qs))

from itertools import combinations
from typing import Sequence
Vector = tuple[bool, ...]
def complete(p: Vector, qs: Sequence[Vector], subset: tuple[int, ...]) -> bool:
    return all(not all(qs[j][w] for j in subset) or p[w] for w in range(len(p)))
def minimal_sets(p: Vector, qs: Sequence[Vector]) -> list[tuple[int, ...]]:
    found: list[tuple[int, ...]] = []
    for size in range(len(qs) + 1):
        for subset in combinations(range(len(qs)), size):
            if not any(set(old).issubset(subset) for old in found) and complete(p, qs, subset):
                found.append(subset)
    return found
p = (True, False, False, False)
qs = [(True, True, False, False), (True, False, True, False), (True, True, True, True)]
print(minimal_sets(p, qs))

