from typing import Sequence
Vector = tuple[bool, ...]
def audit_boundary(p: Vector, qs: Sequence[Vector], observed: int) -> dict[str, object]:
    if any(len(q) != len(p) for q in qs): raise ValueError("length mismatch")
    joint = tuple(all(q[w] for q in qs) for w in range(len(p)))
    return {"forward": all(all((not p[w]) or q[w] for w in range(len(p))) for q in qs),
            "verified": all(q[observed] for q in qs), "coherent": any(joint),
            "backward": all((not joint[w]) or p[w] for w in range(len(p))),
            "counterexamples": [w for w in range(len(p)) if joint[w] and not p[w]]}

from itertools import combinations
from typing import Sequence
Vector = tuple[bool, ...]
def minimal_certificates(p: Vector, qs: Sequence[Vector]) -> list[tuple[int, ...]]:
    answer: list[tuple[int, ...]] = []
    for r in range(len(qs) + 1):
        for s in combinations(range(len(qs)), r):
            complete = all(not all(qs[i][w] for i in s) or p[w] for w in range(len(p)))
            if complete and not any(set(t).issubset(s) for t in answer): answer.append(s)
    return answer

from dataclasses import dataclass, field
import heapq
from typing import Callable, Iterable
@dataclass(order=True)
class State:
    priority: int
    name: str = field(compare=False)
def guided_search(start: str, expand: Callable[[str], Iterable[str]],
                  score: Callable[[str], int], accepts: Callable[[str], bool]) -> str | None:
    heap = [State(-score(start), start)]; seen: set[str] = set()
    while heap:
        state = heapq.heappop(heap).name
        if state in seen: continue
        seen.add(state)
        if accepts(state): return state
        for child in expand(state):
            if child not in seen: heapq.heappush(heap, State(-score(child), child))
    return None

